func:
// Cuando llega un RFID por MQTT, lo guardamos en flow context
// para que el dashboard pueda usarlo cuando el usuario seleccione un libro
const tag = (msg.payload && msg.payload.rfid_tag)
    ? msg.payload.rfid_tag
    : (typeof msg.payload === 'string' ? msg.payload : null);

if (!tag || !/^[A-Fa-f0-9]{4,16}$/.test(tag.trim())) {
    node.warn('RFID recibido inválido: ' + JSON.stringify(msg.payload));
    return null;
}

const rfidLimpio = tag.trim().toUpperCase();
flow.set('ultimo_rfid', rfidLimpio);
flow.set('rfid_ts', new Date().toISOString());

// Consultar el usuario para mostrar en el dashboard
msg.topic = `SELECT id, nombre, apellido, tipo_usuario, activo,
    max_prestamos, fecha_vigencia,
    (SELECT COUNT(*) FROM prestamos WHERE usuario_id = u.id AND estado = 'activo') AS prestamos_actuales
FROM usuarios u WHERE rfid_tag = '${rfidLimpio}' LIMIT 1`;
msg.rfid_tag = rfidLimpio;
return msg;

const rows = msg.payload;
if (!rows || rows.length === 0) {
    msg.payload = JSON.stringify({
        tipo: 'rfid_desconocido',
        mensaje: 'Tag RFID no registrado: ' + msg.rfid_tag,
        ok: false
    });
} else {
    const u = rows[0];
    flow.set('usuario_activo', u);
    msg.payload = JSON.stringify({
        tipo: 'rfid_ok',
        ok: true,
        usuario: {
            id: u.id,
            nombre: u.nombre + ' ' + u.apellido,
            tipo: u.tipo_usuario,
            cupo: u.max_prestamos - u.prestamos_actuales
        },
        mensaje: `✅ ${u.nombre} ${u.apellido} (${u.tipo_usuario}) — Cupo: ${u.max_prestamos - u.prestamos_actuales}`
    });
}
return msg;

msg.req = { headers: { 'x-api-key': 'secreto123' } };
msg.res = null;
msg._mqtt = true;
return msg;

const expectedKey = 'secreto123';
const receivedKey = (msg.req && msg.req.headers)
    ? msg.req.headers['x-api-key']
    : null;

if (receivedKey !== expectedKey) {
    node.warn('API Key inválida');
    msg.payload = { ok: false, error: 'No autorizado' };
    msg.statusCode = 401;
    return [null, msg];
}

msg.scanData = (typeof msg.payload === 'string')
    ? JSON.parse(msg.payload)
    : msg.payload;

return [msg, null];

const scan = msg.scanData || {};

if (!scan.tipo) {
    msg.payload = { ok: false, error: 'Payload inválido: falta campo tipo' };
    msg.statusCode = 400;
    return [null, null, null, msg];
}

msg.origen = scan.origen || 'desconocido';

switch (scan.tipo) {
    case 'identificar_usuario':
        msg.rfid_tag = scan.rfid_tag;
        return [msg, null, null, null];
    case 'prestamo':
        // prestamo ahora puede venir con libro_id en vez de qr_codigo
        msg.rfid_tag = scan.rfid_tag;
        msg.libro_id = scan.libro_id || null;
        msg.qr_codigo = scan.qr_codigo || null;
        return [null, msg, null, null];
    case 'devolucion':
        msg.rfid_tag = scan.rfid_tag;
        msg.qr_codigo = scan.qr_codigo || null;
        msg.prestamo_id = scan.prestamo_id || null;
        return [null, null, msg, null];
    default:
        msg.payload = { ok: false, error: `Tipo desconocido: ${scan.tipo}` };
        msg.statusCode = 400;
        return [null, null, null, msg];
}

const tag = msg.rfid_tag;

if (!tag || typeof tag !== 'string' || tag.trim() === '') {
    msg.payload = { ok: false, error: 'Tag RFID no válido o vacío' };
    msg.statusCode = 400;
    return [null, msg];
}

if (!/^[A-Fa-f0-9]{4,16}$/.test(tag.trim())) {
    msg.payload = { ok: false, error: 'Formato de tag RFID inválido' };
    msg.statusCode = 422;
    return [null, msg];
}

const rfidLimpio = tag.trim().toUpperCase();

msg.topic = `SELECT id, nombre, apellido, email, tipo_usuario, activo,
    max_prestamos, fecha_vigencia,
    (SELECT COUNT(*) FROM prestamos
     WHERE usuario_id = u.id AND estado = 'activo') AS prestamos_actuales
FROM usuarios u
WHERE rfid_tag = '${rfidLimpio}'`;

return [msg, null];

const rows = msg.payload;

if (!rows || rows.length === 0) {
    node.warn(`RFID no registrado: ${msg.rfid_tag}`);
    msg.payload = { ok: false, tipo: 'error', mensaje: 'Tag RFID no encontrado', rfid_tag: msg.rfid_tag };
    msg.statusCode = 404;
    return [msg, null];
}

const usuario = rows[0];

if (!usuario.activo) {
    msg.payload = { ok: false, tipo: 'error', mensaje: `El usuario ${usuario.nombre} está inactivo` };
    msg.statusCode = 403;
    return [msg, null];
}

if (usuario.fecha_vigencia && new Date(usuario.fecha_vigencia) < new Date()) {
    msg.payload = { ok: false, tipo: 'error', mensaje: `Membresía vencida de ${usuario.nombre}` };
    msg.statusCode = 403;
    return [msg, null];
}

msg.usuario = usuario;
msg.payload = {
    ok: true,
    tipo: 'usuario_identificado',
    mensaje: `Lector: ${usuario.nombre} ${usuario.apellido}`,
    datos: {
        Perfil: usuario.tipo_usuario,
        Cupo: `${usuario.prestamos_actuales} de ${usuario.max_prestamos} libros`
    },
    usuario: {
        id: usuario.id,
        tipo: usuario.tipo_usuario,
        cupo_disponible: usuario.max_prestamos - usuario.prestamos_actuales
    }
};
msg.statusCode = 200;
return [null, msg];

// Acepta:
//   a) rfid_tag + libro_id  (nueva ruta web catalog)
//   b) rfid_tag + qr_codigo (ruta legacy / compatibilidad)
const { rfid_tag, libro_id, qr_codigo } = msg;

if (!rfid_tag) {
    msg.payload = { ok: false, error: 'DATOS_INCOMPLETOS', mensaje: 'Se requiere rfid_tag' };
    msg.statusCode = 400;
    return [null, msg];
}
if (!libro_id && !qr_codigo) {
    msg.payload = { ok: false, error: 'DATOS_INCOMPLETOS', mensaje: 'Se requiere libro_id o qr_codigo' };
    msg.statusCode = 400;
    return [null, msg];
}

if (!/^[A-Fa-f0-9]{4,16}$/.test(rfid_tag.trim())) {
    msg.payload = { ok: false, error: 'RFID_INVALIDO', mensaje: 'Formato de RFID inválido' };
    msg.statusCode = 422;
    return [null, msg];
}

const rfidLimpio = rfid_tag.trim().toUpperCase();
msg.rfid_tag = rfidLimpio;

let libroWhere = '';
if (libro_id) {
    libroWhere = `l.id = ${parseInt(libro_id)}`;
} else {
    const qrLimpio = qr_codigo.trim();
    msg.qr_codigo = qrLimpio;
    libroWhere = `l.qr_codigo = '${qrLimpio}'`;
}

msg.topic = `
SELECT
    u.id AS usuario_id,
    u.nombre || ' ' || u.apellido AS usuario_nombre,
    u.activo AS usuario_activo,
    u.fecha_vigencia,
    u.max_prestamos,
    (SELECT COUNT(*) FROM prestamos
     WHERE usuario_id = u.id AND estado = 'activo') AS prestamos_actuales,
    l.id AS libro_id,
    l.titulo,
    l.autor,
    l.qr_codigo,
    e.id AS ejemplar_id,
    e.estado AS ejemplar_estado
FROM usuarios u, libros l
LEFT JOIN ejemplares e ON e.libro_id = l.id AND e.estado = 'disponible'
WHERE u.rfid_tag = '${rfidLimpio}' AND ${libroWhere}
LIMIT 1`;

return [msg, null];

const rows = msg.payload;

if (!rows || rows.length === 0) {
    msg.payload = { ok: false, error: 'TAG_NO_REGISTRADO', mensaje: 'RFID no encontrado' };
    msg.statusCode = 404;
    return [null, msg];
}

const data = rows[0];

if (!data.libro_id) {
    msg.payload = { ok: false, error: 'LIBRO_NO_ENCONTRADO', mensaje: 'El libro no existe en el catálogo' };
    msg.statusCode = 404;
    return [null, msg];
}

if (!data.usuario_activo) {
    msg.payload = { ok: false, error: 'USUARIO_INACTIVO', mensaje: 'Usuario inactivo' };
    msg.statusCode = 403;
    return [null, msg];
}

if (data.fecha_vigencia && new Date(data.fecha_vigencia) < new Date()) {
    msg.payload = { ok: false, error: 'MEMBRESIA_VENCIDA', mensaje: 'Membresía vencida' };
    msg.statusCode = 403;
    return [null, msg];
}

if (data.prestamos_actuales >= data.max_prestamos) {
    msg.payload = {
        ok: false,
        error: 'CUPO_AGOTADO',
        mensaje: `${data.usuario_nombre} ya tiene ${data.prestamos_actuales}/${data.max_prestamos} préstamos activos`
    };
    msg.statusCode = 409;
    return [null, msg];
}

if (data.ejemplar_estado !== 'disponible' || !data.ejemplar_id) {
    msg.payload = {
        ok: false,
        error: 'SIN_EJEMPLARES',
        mensaje: `"${data.titulo}" no tiene ejemplares disponibles`
    };
    msg.statusCode = 409;
    return [null, msg];
}

msg.prestamo_data = data;

const diasPrestamo = 14;
const devolucion = new Date();
devolucion.setDate(devolucion.getDate() + diasPrestamo);
msg.fecha_devolucion = devolucion.toISOString().replace('T', ' ').substring(0, 19);

const qrVal = data.qr_codigo || msg.qr_codigo || '';
const rfidVal = msg.rfid_tag || '';

msg.topic = `BEGIN TRANSACTION;
UPDATE ejemplares SET estado = 'prestado' WHERE id = ${data.ejemplar_id};
INSERT INTO prestamos
    (usuario_id, ejemplar_id, fecha_devolucion_esperada, estado, rfid_prestamo, qr_prestamo)
VALUES
    (${data.usuario_id}, ${data.ejemplar_id}, '${msg.fecha_devolucion}', 'activo',
     '${rfidVal}', '${qrVal}');
INSERT INTO audit_log (tipo, origen, usuario_id, ejemplar_id, mensaje, payload_raw)
VALUES ('prestamo', 'web_catalog', ${data.usuario_id}, ${data.ejemplar_id},
    'Préstamo registrado: ${data.titulo.replace(/'/g, "''")}', '${JSON.stringify({rfid: rfidVal, libro_id: data.libro_id})}');
COMMIT;`;

return [msg, null];

const data = msg.prestamo_data;

msg.payload = {
    ok: true,
    tipo: 'prestamo_exitoso',
    mensaje: `Préstamo: ${data.titulo}`,
    datos: {
        Usuario: data.usuario_nombre,
        Vence: msg.fecha_devolucion.substring(0, 10)
    },
    prestamo: {
        usuario: data.usuario_nombre,
        libro: data.titulo,
        autor: data.autor,
        ejemplar_id: data.ejemplar_id,
        fecha_devolucion_esperada: msg.fecha_devolucion
    }
};
msg.statusCode = 201;
return msg;

const { rfid_tag, qr_codigo, prestamo_id } = msg;

if (!rfid_tag) {
    msg.payload = { ok: false, error: 'DATOS_INCOMPLETOS', mensaje: 'Se requiere rfid_tag' };
    msg.statusCode = 400;
    return [null, msg];
}

const rfidLimpio = rfid_tag.trim().toUpperCase();
msg.rfid_tag = rfidLimpio;

let whereClause = '';
if (prestamo_id) {
    whereClause = `p.id = ${parseInt(prestamo_id)} AND u.rfid_tag = '${rfidLimpio}'`;
} else if (qr_codigo) {
    const qrLimpio = qr_codigo.trim();
    whereClause = `u.rfid_tag = '${rfidLimpio}' AND l.qr_codigo = '${qrLimpio}'`;
} else {
    msg.payload = { ok: false, error: 'DATOS_INCOMPLETOS', mensaje: 'Se requiere qr_codigo o prestamo_id' };
    msg.statusCode = 400;
    return [null, msg];
}

msg.topic = `
SELECT
    p.id AS prestamo_id,
    p.ejemplar_id,
    p.fecha_prestamo,
    p.fecha_devolucion_esperada,
    u.nombre || ' ' || u.apellido AS usuario_nombre,
    l.titulo,
    l.autor,
    CASE WHEN p.fecha_devolucion_esperada < datetime('now','localtime') THEN 1 ELSE 0 END AS vencido
FROM prestamos p
JOIN usuarios   u ON p.usuario_id  = u.id
JOIN ejemplares e ON p.ejemplar_id = e.id
JOIN libros     l ON e.libro_id    = l.id
WHERE ${whereClause}
  AND p.estado = 'activo'
LIMIT 1`;

return [msg, null];

const rows = msg.payload;

if (!rows || rows.length === 0) {
    msg.payload = {
        ok: false,
        error: 'PRESTAMO_NO_ENCONTRADO',
        mensaje: 'No se encontró un préstamo activo para este usuario y libro'
    };
    msg.statusCode = 404;
    return [null, msg];
}

const prestamo = rows[0];
msg.prestamo_data = prestamo;

const ahora = new Date().toISOString().replace('T', ' ').substring(0, 19);

msg.topic = `BEGIN TRANSACTION;
UPDATE prestamos
    SET estado = 'devuelto',
        fecha_devolucion_real = '${ahora}',
        rfid_devolucion = '${msg.rfid_tag}'
    WHERE id = ${prestamo.prestamo_id};
UPDATE ejemplares
    SET estado = 'disponible'
    WHERE id = ${prestamo.ejemplar_id};
INSERT INTO audit_log (tipo, origen, mensaje, payload_raw)
    VALUES ('devolucion', 'iot',
        'Devolución registrada: ${prestamo.titulo.replace(/'/g, "''")} por ${prestamo.usuario_nombre.replace(/'/g, "''")}',
        '${JSON.stringify({ prestamo_id: prestamo.prestamo_id })}');
COMMIT;`;

return [msg, null];

const prestamo = msg.prestamo_data;
const ahora = new Date().toISOString().replace('T', ' ').substring(0, 19);
const vencido = prestamo.vencido === 1;

msg.payload = {
    ok: true,
    tipo: vencido ? 'devolucion_tardía' : 'devolucion_exitosa',
    mensaje: vencido
        ? `Devolución TARDÍA: ${prestamo.titulo}`
        : `Devolución OK: ${prestamo.titulo}`,
    datos: {
        Usuario: prestamo.usuario_nombre,
        Retraso: vencido ? `${Math.ceil((new Date().getTime() - new Date(prestamo.fecha_devolucion_esperada).getTime()) / 86400000)} días` : 'Ninguno'
    },
    devolucion: {
        usuario: prestamo.usuario_nombre,
        libro: prestamo.titulo,
        autor: prestamo.autor,
        fecha_devolucion_real: ahora,
        fecha_devolucion_esperada: prestamo.fecha_devolucion_esperada
    }
};
msg.statusCode = 200;
return msg;

msg.topic = `SELECT * FROM estadisticas_dashboard;
SELECT * FROM prestamos_activos ORDER BY vencido DESC, fecha_devolucion_esperada ASC LIMIT 20;`;
return msg;

const results = Array.isArray(msg.payload) ? msg.payload : [msg.payload];
msg.payload = {
    ok: true,
    timestamp: new Date().toISOString(),
    estadisticas: results[0] && results[0][0] ? results[0][0] : {},
    prestamos_activos: results[1] || []
};
msg.statusCode = 200;
return msg;

msg.payload = { ok: true, libros: msg.payload || [] };
msg.statusCode = 200;
return msg;

msg.payload = { ok: true, registros: msg.payload || [] };
msg.statusCode = 200;
return msg;

msg.payload = { ok: true, deudores: msg.payload || [] };
msg.statusCode = 200;
return msg;

const d = (typeof msg.payload === 'string') ? JSON.parse(msg.payload) : msg.payload;

if (!d || !d.usuario_id) {
    msg.payload = { ok: false, error: 'usuario_id requerido' };
    msg.statusCode = 400;
    return [null, msg];
}

msg.ban_data = d;

// Construir prompt para Gemini
const diasDeuda = d.vencimiento_mas_antiguo
    ? Math.ceil((new Date() - new Date(d.vencimiento_mas_antiguo)) / 86400000)
    : '?';

msg.gemini_prompt = `Eres el sistema de la Biblioteca Universitaria BiblioSys.
Redacta un correo electrónico formal pero con un tono memorable (puede tener un poco de dramatismo cortés) notificando al usuario que su acceso ha sido SUSPENDIDO por préstamos vencidos.

Datos del usuario:
- Nombre: ${d.nombre} ${d.apellido}
- Tipo de usuario: ${d.tipo_usuario}
- Email: ${d.email}
- Libros pendientes: ${d.libros_pendientes || 'no especificados'}
- Préstamos vencidos: ${d.prestamos_vencidos}
- Días de atraso máximo: ${diasDeuda} días

El correo debe:
1. Saludar formalmente usando el nombre completo
2. Mencionar específicamente los libros que no ha devuelto
3. Indicar que el acceso está suspendido hasta regularizar
4. Dar instrucciones claras para reactivar (devolver libros en biblioteca)
5. Firmar como "Sistema BiblioSys - Biblioteca Universitaria"

Solo devuelve el correo, sin explicaciones adicionales.`;

return [msg, null];

// Llamada a Gemini Flash 2.0 para generar el mensaje de baneo
// La API key se lee de variable de entorno GEMINI_API_KEY
const apiKey = env.get('GEMINI_API_KEY') || '';

if (!apiKey) {
    node.warn('GEMINI_API_KEY no configurada en variables de entorno de Node-RED');
    msg.gemini_texto = '[Error: GEMINI_API_KEY no configurada. Configúrala en Settings > Environment Variables]';
    return msg; // Continúa sin Gemini para no bloquear el baneo
}

const prompt = msg.gemini_prompt;
const url = `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key=${apiKey}`;

// Usamos un nodo function con fetch async
const body = JSON.stringify({
    contents: [{ parts: [{ text: prompt }] }],
    generationConfig: { temperature: 0.8, maxOutputTokens: 600 }
});

try {
    const response = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: body
    });
    const data = await response.json();
    if (data.candidates && data.candidates[0]) {
        msg.gemini_texto = data.candidates[0].content.parts[0].text;
    } else {
        msg.gemini_texto = '[Gemini no devolvió respuesta: ' + JSON.stringify(data.error || data) + ']';
    }
} catch(e) {
    msg.gemini_texto = '[Error llamando Gemini: ' + e.message + ']';
    node.error('Gemini error: ' + e.message);
}

return msg;

const d = msg.ban_data;
const correoGenerado = msg.gemini_texto || '';

// Desactivar usuario y registrar en audit_log
msg.topic = `BEGIN TRANSACTION;
UPDATE usuarios SET activo = 0 WHERE id = ${d.usuario_id};
INSERT INTO audit_log (tipo, origen, usuario_id, mensaje, payload_raw)
VALUES ('baneo', 'api', ${d.usuario_id},
    'Usuario baneado por préstamos vencidos. Email generado con Gemini enviado a ${(d.email||'').replace(/'/g,"''")}',
    '${JSON.stringify({prestamos_vencidos: d.prestamos_vencidos, libros: d.libros_pendientes}).replace(/'/g, "''")}');
COMMIT;`;

msg.correo_gemini = correoGenerado;
msg.ban_usuario = d;
return msg;

const d = msg.ban_usuario;
msg.payload = {
    ok: true,
    mensaje: `Usuario ${d.nombre} ${d.apellido} baneado correctamente`,
    email_generado: msg.correo_gemini,
    usuario: d
};
msg.statusCode = 200;
return msg;

// Endpoint específico para el dashboard web:
// Recibe { libro_id } y toma el RFID del flow context
const d = (typeof msg.payload === 'string') ? JSON.parse(msg.payload) : msg.payload;

const rfid = flow.get('ultimo_rfid');
const rfid_ts = flow.get('rfid_ts');

if (!rfid) {
    msg.payload = { ok: false, error: 'SIN_RFID', mensaje: 'No hay ningún tag RFID activo. Acerca tu tarjeta al lector primero.' };
    msg.statusCode = 400;
    return [null, msg];
}

// Verificar que el RFID no sea demasiado viejo (5 minutos)
if (rfid_ts) {
    const segundos = (new Date() - new Date(rfid_ts)) / 1000;
    if (segundos > 300) {
        flow.set('ultimo_rfid', null);
        flow.set('usuario_activo', null);
        msg.payload = { ok: false, error: 'RFID_EXPIRADO', mensaje: 'La sesión RFID expiró. Vuelve a acercar tu tarjeta al lector.' };
        msg.statusCode = 400;
        return [null, msg];
    }
}

if (!d || !d.libro_id) {
    msg.payload = { ok: false, error: 'LIBRO_REQUERIDO', mensaje: 'Selecciona un libro del catálogo' };
    msg.statusCode = 400;
    return [null, msg];
}

// Reutilizar el flujo principal de préstamo
msg.scanData = {
    tipo: 'prestamo',
    rfid_tag: rfid,
    libro_id: d.libro_id,
    origen: 'web_catalog'
};
msg.rfid_tag = rfid;
msg.libro_id = d.libro_id;

// Necesitamos un req/res falso para que el flujo funcione sin API key check
// porque este endpoint es interno del dashboard
msg.req = msg.req || { headers: {} };
msg.origen = 'web_catalog';

return [msg, null];

if (env.get('NODE_ENV') !== 'production') {
    node.log(`[AUDIT] ${msg.payload && msg.payload.accion || 'evento'}: ${JSON.stringify(msg.payload)}`);
}
return null;

const d = msg.payload;
msg.topic = `INSERT INTO usuarios (nombre, apellido, email, rfid_tag, tipo_usuario, max_prestamos, fecha_vigencia, activo) VALUES ('${d.nombre}', '${d.apellido}', '${d.email}', '${d.rfid_tag}', '${d.tipo_usuario}', ${d.max_prestamos}, ${d.fecha_vigencia ? `'${d.fecha_vigencia}'` : 'NULL'}, 1);`;
return msg;

const d = msg.payload;
msg.topic = `
BEGIN TRANSACTION;
INSERT INTO libros (titulo, autor, isbn, editorial, anio_publicacion, qr_codigo)
VALUES ('${d.titulo}', '${d.autor}', '${d.isbn}', '${d.editorial}', ${d.anio || 'NULL'}, '${d.qr_codigo}');
INSERT INTO ejemplares (libro_id, estado)
VALUES (last_insert_rowid(), 'disponible');
COMMIT;
`;
return msg;

msg.payload = { ok: true };
msg.statusCode = 201;
return msg;

const tipo = msg.payload.tipo || 'manual';
const ahora = new Date();
const timestamp = ahora.toISOString()
    .replace(/[:.]/g, '-')
    .replace('T', '_')
    .substring(0, 19);

const DB_PATH    = env.get('SQLITE_DB_PATH') || '/data/biblioteca/biblioteca.db';
const BACKUP_DIR = env.get('BACKUP_DIR')     || '/data/backups';
const MAX_BACKUPS = parseInt(env.get('MAX_BACKUPS') || '30');

const backupFile = `${BACKUP_DIR}/biblioteca_${tipo}_${timestamp}.db`;

msg.payload = [
    `mkdir -p ${BACKUP_DIR}`,
    `sqlite3 ${DB_PATH} ".timeout 5000" ".backup ${backupFile}"`,
    `gzip -9 ${backupFile}`,
    `ls -t ${BACKUP_DIR}/biblioteca_*.db.gz | tail -n +${MAX_BACKUPS + 1} | xargs -r rm --`
].join(' && ');

msg.backup_meta = { tipo, timestamp, archivo: backupFile + '.gz' };
node.log(`Iniciando backup ${tipo}: ${backupFile}.gz`);
return msg;

const meta = msg.backup_meta || {};
msg.topic = `INSERT INTO audit_log (tipo, origen, mensaje)
    VALUES ('backup', 'sistema', 'Respaldo ${meta.tipo || ''} completado: ${meta.archivo || ''}');`;
node.status({ fill: 'green', shape: 'dot', text: `OK ${meta.timestamp}` });
node.log(`Backup completado: ${meta.archivo}`);
return msg;

const err = msg.payload || 'Error desconocido';
node.error(`Error en backup: ${err}`);
node.status({ fill: 'red', shape: 'ring', text: 'ERROR backup' });
msg.topic = `INSERT INTO audit_log (tipo, origen, mensaje)
    VALUES ('backup', 'sistema', 'ERROR en respaldo: ${String(err).replace(/'/g, "''")}');`;
return msg;
